    statue(x,z){ const g=part(x,z); g.position.y=0.01; const S=1.25; const inner=new THREE.Group(); inner.scale.set(S,S,S); g.add(inner); inner.add(box(0.62,0.12,0.62,M(CL.grey),0,0.06)); inner.add(box(0.46,0.3,0.46,M(CL.silver),0,0.27)); inner.add(box(0.34,0.22,0.34,M(CL.grey),0,0.53)); const pat=M(CL.patina); inner.add(cyl(0.1,0.2,0.62,pat,0,0.95)); inner.add(cyl(0.11,0.1,0.18,pat,0,1.33)); inner.add(sph(0.075,pat,0,1.47)); for(let i=0;i<7;i++){ const sp=box(0.016,0.12,0.016,pat,0,1.55,0); sp.position.x=Math.cos(Math.PI/6*(i+0.5)+Math.PI/12)*0.07; sp.position.z=-Math.sin(Math.PI/6*(i+0.5)+Math.PI/12)*0.07; sp.rotation.z=-Math.cos(Math.PI/6*(i+0.5)+Math.PI/12)*0.5; sp.rotation.x=Math.sin(Math.PI/6*(i+0.5)+Math.PI/12)*0.5; inner.add(sp); } const arm=cyl(0.03,0.035,0.5,pat,0.13,1.5); arm.rotation.z=-0.35; inner.add(arm); inner.add(cyl(0.035,0.025,0.14,M(CL.gold),0.3,1.78)); const fl=cyl(0,0.07,0.2,M(CL.gold,{emissive:0xa05000}),0.3,1.95); inner.add(fl); pulsers.push({o:fl,amp:0.25,sp:0.012}); const tab=box(0.12,0.17,0.04,pat,-0.17,1.12); tab.rotation.y=0.3; inner.add(tab); const arm2=cyl(0.03,0.03,0.28,pat,-0.12,1.15); arm2.rotation.z=0.9; inner.add(arm2); return g; },
    buffalo(x,z){ const g=part(x,z); const hide=M(CL.hide); const body=sph(0.3,hide,0,0.36); body.scale.set(1.1,0.75,0.6); g.add(body); const hump=sph(0.2,hide,0.12,0.5); hump.scale.set(1,0.8,0.7); g.add(hump); const head=box(0.22,0.22,0.2,M(0x3f2816),0.38,0.34); g.add(head); g.add(sph(0.04,M(CL.dark),0.5,0.3)); for(const s of [-1,1]){ const horn=cyl(0.012,0.025,0.14,M(CL.light),0.4,0.5,s*0.1); horn.rotation.x=s*0.9; g.add(horn); } for(const [lx,lz] of [[-0.2,-0.09],[-0.2,0.09],[0.2,-0.09],[0.2,0.09]]) g.add(cyl(0.035,0.04,0.26,M(0x3f2816),lx,0.13,lz)); const tail=cyl(0.01,0.01,0.22,M(0x3f2816),-0.34,0.35); tail.rotation.z=0.5; g.add(tail); g.add(sph(0.03,M(CL.dark),-0.4,0.26)); bobbers.push({o:head,amp:0.015,sp:0.002,ph:0}); return g; },
    drum(x,z){ const g=part(x,z); const inner=new THREE.Group(); inner.position.y=0.95; inner.rotation.z=-0.35; g.add(inner);
      // crispy skin texture
      const cv=document.createElement('canvas'); cv.width=cv.height=128; const c=cv.getContext('2d'); c.fillStyle='#c97a24'; c.fillRect(0,0,128,128); let sd=99; const rnd=()=>{ sd=(sd*16807)%2147483647; return sd/2147483647; }; for(let i=0;i<900;i++){ const r=rnd(); c.fillStyle= r<0.35?'rgba(120,55,10,.55)': r<0.7?'rgba(255,170,70,.45)':'rgba(90,35,5,.35)'; const s=1+rnd()*3; c.fillRect(rnd()*128,rnd()*128,s,s*0.7); } const skin=new THREE.CanvasTexture(cv); skin.wrapS=skin.wrapT=THREE.RepeatWrapping; skin.repeat.set(2,1);
      const meatMat=new THREE.MeshStandardMaterial({map:skin,color:0xffffff,roughness:.32,metalness:.05,emissive:0x3a1a05,emissiveIntensity:.35});
      const prof=[[0.0,0.0],[0.06,0.01],[0.11,0.05],[0.145,0.11],[0.155,0.18],[0.14,0.25],[0.105,0.31],[0.065,0.35],[0.04,0.38],[0.03,0.4]].map(p=>new THREE.Vector2(p[0],p[1]));
      const meat=new THREE.Mesh(new THREE.LatheGeometry(prof,28),meatMat); meat.position.y=-0.2; inner.add(meat);
      const bump=sph(0.07,meatMat,0.08,-0.06); bump.scale.set(1.2,0.8,1); inner.add(bump);
      const bone=cyl(0.022,0.028,0.22,M(0xf3ead8,{roughness:.6}),0,0.3); inner.add(bone);
      inner.add(sph(0.038,M(0xf3ead8,{roughness:.6}),0.03,0.42)); inner.add(sph(0.038,M(0xf3ead8,{roughness:.6}),-0.03,0.42));
      const drip=sph(0.025,M(0xb0341a,{roughness:.2,emissive:0x3a0000}),0.12,-0.3); drip.scale.y=1.6; inner.add(drip);
      // feathered wings, flapping
      const wings=[]; for(const s of [-1,1]){ const w=new THREE.Group(); w.position.set(s*0.12,0.05,0); for(let i=0;i<3;i++){ const f=box(0.22-i*0.04,0.012,0.09-i*0.015,M(i===0?0xffc857:0xffe29a,{roughness:.5}),0,0,0); f.geometry.translate((0.22-i*0.04)/2*s,0,0); f.position.set(0,-i*0.012,-i*0.035); f.rotation.y=s*i*0.18; w.add(f); } const pri=box(0.12,0.01,0.05,M(0xffe29a),0,0,0); pri.geometry.translate(0.06*s,0,0); pri.position.set(s*0.2,0.005,0.03); pri.rotation.y=-s*0.4; w.add(pri); inner.add(w); wings.push([w,s]); }
      animators.push(now=>{ for(const [w,s] of wings){ w.rotation.z=s*(0.35+Math.sin(now*0.014)*0.5); } });
      bobbers.push({o:inner,amp:0.1,sp:0.0022,ph:1}); spinners.push({o:inner,ax:'y',v:0.008});
      const shadow=new THREE.Mesh(new THREE.CircleGeometry(0.16,20),new THREE.MeshBasicMaterial({color:0x000000,transparent:true,opacity:.22,depthWrite:false})); shadow.material.userData.baseOpacity=.22; shadow.rotation.x=-Math.PI/2; shadow.position.y=0.012; g.add(shadow);
      return g; },
