    canyon(x,z,len){ const g=part(x,z); const L=len*PS; const cols=[0xb86a3a,0xd49a5a,0xe6b57a,0xb3573a,0xd48a5a]; for(const s of [-1,1]){ for(let i=0;i<5;i++){ g.add(box(L,0.07,0.22,M(cols[i]),0,-0.33+i*0.07,s*(0.22+i*0.03))); } } const riv=box(L,0.01,0.1,flowMat(.8),0,-0.36); g.add(riv); g.add(box(L,0.4,0.04,M(CL.purple),0,-0.2,0)); g.children[g.children.length-1].visible=false; return g; },
