    potato(x,z){ const g=part(x,z); g.add(box(0.7,0.06,0.3,M(COL.red),0,0.1)); g.add(box(0.2,0.14,0.28,M(COL.red),-0.3,0.2)); for(const [wx,wz] of [[-0.2,-0.14],[-0.2,0.14],[0.2,-0.14],[0.2,0.14]]){ const w=cyl(0.05,0.05,0.04,M(CL.dark),wx,0.05,wz); w.rotation.x=Math.PI/2; g.add(w); } const p=sph(0.17,M(0x9b6b3f,{roughness:1}),0.08,0.28); p.scale.set(1.5,0.8,0.9); g.add(p); return g; },
    cheese(x,z){ const g=part(x,z); const sh=new THREE.Shape([new THREE.Vector2(0,0),new THREE.Vector2(0.4,0),new THREE.Vector2(0,0.3)]); const w=new THREE.Mesh(new THREE.ExtrudeGeometry(sh,{depth:0.22,bevelEnabled:false}),M(0xffd54f)); w.rotation.x=-Math.PI/2; w.position.set(-0.1,0.22,0.15); g.add(w); for(const [hx,hz] of [[0.08,0.06],[0.18,0.1],[0.1,0.16]]) g.add(sph(0.025,M(0xd9a000),hx-0.1,0.225,hz)); return g; },
    coaster(x,z,len){ const g=part(x,z); const L=len*PS; const pts=[]; for(let i=0;i<=40;i++){ const t=i/40; pts.push([-L/2+L*t, 0.25+Math.abs(Math.sin(t*Math.PI*2.5))*0.9*(1-t*0.4), Math.sin(t*Math.PI*2)*0.2]); } const curve=new THREE.CatmullRomCurve3(pts.map(p=>new THREE.Vector3(...p))); g.add(new THREE.Mesh(new THREE.TubeGeometry(curve,80,0.018,6,false),M(COL.red))); for(let i=0;i<=12;i++){ const p=curve.getPoint(i/12); g.add(box(0.015,p.y,0.015,M(CL.iron),p.x,p.y/2,p.z)); } const car=box(0.1,0.05,0.07,M(CL.gold),0,0); g.add(car); animators.push(now=>{ const t=(now*0.00012)%1; const p=curve.getPoint(t); car.position.set(p.x,p.y+0.04,p.z); const q=curve.getPoint(Math.min(1,t+0.01)); car.lookAt(q.x,q.y+0.04,q.z); }); return g; },
    ppg(x,z,h){ const g=part(x,z); const m=glassMat(6,22,0.3,'#1f2a33'); g.add(box(0.3,h,0.3,m,0,h/2)); for(let i=0;i<4;i++){ const a=i*Math.PI/2+Math.PI/4; g.add(cyl(0,0.035,0.25,m,Math.cos(a)*0.16,h+0.125,Math.sin(a)*0.16,4)); } for(let i=0;i<4;i++){ const a=i*Math.PI/2; g.add(cyl(0,0.03,0.2,m,Math.cos(a)*0.15,h+0.1,Math.sin(a)*0.15,4)); } g.add(cyl(0,0.05,0.3,m,0,h+0.15,0,4)); return g; },
    cityhall(x,z,h){ const g=part(x,z); const m=M(0xd9d4c7); g.add(box(0.7,0.3,0.5,m,0,0.15)); g.add(box(0.22,h,0.22,m,0,h/2+0.3)); g.add(box(0.12,0.12,0.23,M(CL.dark),0,h*0.8+0.3)); g.add(cyl(0.07,0.1,0.1,m,0,h+0.35)); g.add(cyl(0.02,0.03,0.18,M(0x3a6a5a),0,h+0.49)); g.add(sph(0.03,M(0x3a6a5a),0,h+0.6)); return g; },
