    keytower(x,z,h){ const g=part(x,z); g.add(box(0.26,h*0.85,0.26,glassMat(5,26,0.4,'#4a4a52'),0,h*0.425)); g.add(pyramidG(0.19,h*0.15,4,M(CL.silver),0,h*0.925)); return g; },
