    splitrock(x,z){ const g=part(x,z); g.add(box(0.4,0.3,0.4,M(CL.rock,{flatShading:true}),0,0.15)); const l=PR.lh(0,0,0.8); l.position.set(0,0.3,0); g.add(l); return g; },
