    const bn=new THREE.Mesh(boxGeo,M(CL.teal)); bn.position.set(4.35,0,1.55); bn.scale.set(0.65,0.001,0.65); stage.add(bn); dataBars.push({m:bn,h:Math.max(0.02,n27*kn),lab:fmt(n27),x:4.35,z:1.55});
